# 1급 CH4 수동태 (31~40) 2차 감수
X(1, 31, r="수동태 뒤에 by가 아닌 전치사를 쓰는 표현을 묶어서 익힌다: be interested in, be crowded/filled/packed with, be known for, be worried about, be satisfied with, be surprised at, be proud of.",
  n=["be interested in, be crowded with를 바르게 짝지었으므로", "interested 뒤에 at, crowded 뒤에 by를 쓰지 않으므로", "두 전치사의 자리가 서로 바뀌었으므로", "interested 뒤에 by, crowded 뒤에 of를 쓰지 않으므로", "interested 뒤에 about, crowded 뒤에 for를 쓰지 않으므로"],
  st="① 빈칸 앞의 과거분사 두 개를 본다: {0}. → ② 둘 다 by가 아니라 정해진 전치사와 짝을 이루는 표현이다: {1}. → ③ 순서대로 맞춘 {a}를 고른다.",
  R=("interested, crowded", "be interested in(~에 관심이 있다), be crowded with(~로 붐비다)"), B=("known, filled", "be known for(~로 유명하다), be filled with(~로 가득 차다)"),
  C=("worried, crowded", "be worried about(~을 걱정하다), be crowded with(~로 붐비다)"), D=("proud, packed", "be proud of(~을 자랑스러워하다), be packed with(~로 꽉 차다)"),
  E=("satisfied, lined", "be satisfied with(~에 만족하다), be lined with(~가 늘어서 있다)"), F=("surprised, loaded", "be surprised at(~에 놀라다), be loaded with(~가 가득 실려 있다)"))

X(1, 32, r="조동사나 have to가 있는 문장의 수동태는 ‘조동사(have to) + be + 과거분사’로 쓴다. have to의 to 뒤에는 동사원형 be가 온다.",
  n=["has 뒤에 to가 없고 clean도 과거분사가 아니므로", "to clean은 능동이라 ‘교실이 청소되어야 한다’는 수동의 뜻이 되지 않으므로", "has been cleaned는 ‘청소되었다’는 현재완료 수동태라 have to의 의무 뜻이 사라지므로",
     "to be cleaning은 진행형 능동이라 수동의 뜻이 되지 않으므로", "has to 뒤에 수동의 동사원형 be cleaned를 써서 ‘청소되어야 한다’를 나타냈으므로"],
  st="① 능동문에서 조동사 부분({0})과 동사({1})를 나눈다. → ② 수동태에서도 조동사 부분은 그대로 두고, 동사만 ‘be + 과거분사’로 바꾼다. → ③ 빈칸 앞에 남아 있는 말({2}) 뒤에 이어지도록 {a}를 고른다.",
  R=("have to", "clean", "has"), B=("must", "finish", "must"), C=("has to", "repair", "has"), D=("need to", "update", "needs"), E=("are going to", "announce", "is going"), F=("should", "lock", "should"))

X(1, 33, r="advise, tell, ask, encourage + 목적어 + to부정사 문장을 수동태로 바꾸면 ‘be + 과거분사 + to부정사’가 된다. to부정사는 그대로 남는다.",
  n=["주어 The employees가 복수이고 과거의 일이라 were를 바르게 썼으므로", "advise의 과거분사 advised를 바르게 썼으므로", "능동문의 to attend는 수동태에서도 to부정사로 남아야 하는데 to attending으로 썼으므로",
     "attend의 목적어를 그대로 썼으므로", "능동문의 주어를 by + 행위자로 바르게 나타냈으므로"],
  st="① 능동문에서 ‘동사 + 목적어 + to부정사’를 찾는다: {0}. → ② 수동태에서는 목적어가 주어로 나가고 동사가 be + 과거분사가 될 뿐, to부정사({1})는 모양이 바뀌지 않는다. → ③ {n}은 to 뒤에 -ing형을 썼으므로 틀렸다.",
  R=("advised the employees to attend", "to attend"), B=("advised Mina to leave", "to leave"), C=("advised the patient to rest", "to rest"), D=("told the students to wait", "to wait"),
  E=("asked Tom to stay", "to stay"), F=("encouraged us to practice", "to practice"))

X(1, 34, r="It is believed/said that + 주어 + 동사 ~는 ‘주어 + is believed/said + to부정사’로 바꿀 수 있다. that절의 일이 주절보다 먼저 일어났으면 완료부정사(to have + 과거분사)를 쓰고, 수동이면 to have been + 과거분사가 된다.",
  n=["is believed 뒤에 동사 was를 바로 이어 쓸 수 없으므로", "is believed 뒤에는 being이 아니라 to부정사가 와야 하므로", "믿는 것은 현재, 만들어진 것은 과거이므로 완료부정사 to have been (created)로 바르게 나타냈으므로",
     "will be는 미래를 나타내고 is believed 뒤에 올 수 없으므로", "주어를 문장 앞으로 꺼낸 뒤에는 that절을 쓸 수 없으므로"],
  st="① 첫 문장에서 주절과 that절의 시제를 견준다: {0}. → ② that절의 주어를 문장 앞으로 꺼내면 동사는 to부정사가 되는데, that절이 한 시제 앞서므로 to have + 과거분사를 쓴다. → ③ {1} 정답은 {a}.",
  R=("주절은 현재(is believed), that절은 과거(was created)", "빈칸 뒤에 과거분사 created가 있으므로 수동의 been까지 넣는다."),
  B=("주절은 현재(say), that절은 과거(was discovered)", "빈칸 뒤에 과거분사 discovered가 있으므로 수동의 been까지 넣는다."),
  C=("주절은 현재(say), that절은 과거(was written)", "빈칸 뒤에 과거분사 written이 있으므로 수동의 been까지 넣는다."),
  D=("주절은 현재(believe), that절은 과거(was built)", "다리는 지어지는 대상이므로 수동의 been built까지 넣는다. to be built는 시제가, to have built는 태가 틀렸다."),
  E=("주절은 현재(think), that절은 과거(was stolen)", "그림은 도난당한 대상이므로 수동의 been stolen까지 넣는다. to be stolen은 시제가, to have stolen은 태가 틀렸다."),
  F=("주절은 현재(believe), that절은 과거(was destroyed)", "마을은 파괴된 대상이므로 수동의 been destroyed까지 넣는다. to be destroyed는 시제가, to have destroyed는 태가 틀렸다."))

X(1, 35, r="목적격 보어가 to부정사인 5형식 문장의 수동태는 ‘be + 과거분사 + to부정사’이고, call off, look into 같은 구동사의 수동태에서는 전치사·부사를 빠뜨리지 않는다.",
  pre=["문장별 판정: a) X. to completing을 to complete로 써야 한다. b) O. call off를 한 덩어리로 수동태로 만들었다. c) X. advised 뒤에는 working이 아니라 to work가 와야 한다. d) O. be allowed to + 동사원형. e) X. look into의 into가 빠졌다(was looked into)."],
  k="틀린 문장은 a, c, e이다.",
  n=["b는 옳은 문장이므로", "b, d는 옳은 문장이므로", "d는 옳은 문장이고 틀린 문장 c가 빠졌으므로", "b, d는 옳은 문장이므로", "틀린 문장 a, c, e만 모았으므로"],
  st="① 화살표 앞뒤를 견주며 두 가지만 본다. 능동문의 to부정사가 수동문에서도 to부정사로 남았는지, 구동사의 전치사·부사가 수동문에 남았는지. → ② {0} → ③ 틀린 세 문장을 모은 {a}를 고른다.",
  R="a는 to completing, c는 working으로 to부정사가 깨졌고, e는 look into의 into가 빠졌다. b의 was called off와 d의 were allowed to work는 옳다.",
  B="b는 to submitting, d는 warming up으로 to부정사가 깨졌고, e는 take care of의 of가 빠졌다. a의 were permitted to use와 c의 was put off는 옳다.",
  C="c는 being quiet, e는 stay로 to부정사가 깨졌고, b는 look for의 for가 빠졌다. a의 was encouraged to join과 d의 was turned down은 옳다.",
  D="a는 staying으로 to부정사가 깨졌고, d는 put out의 out이, e는 laugh at의 at이 빠졌다. b의 were brought up과 c의 was expected to win은 옳다.",
  E="c는 paying, e는 buy로 to부정사가 깨졌고, d는 hand in의 in이 빠졌다. a의 was allowed to leave와 b의 was looked up to by는 옳다.",
  F="a는 to returning으로 to부정사가 깨졌고, b는 carry out의 out이, d는 deal with의 with가 빠졌다. c의 were invited to have와 e의 was ordered to stop은 옳다.")

X(1, 36, r="be filled with처럼 수동태 뒤에 정해진 전치사를 쓰는 표현은 ‘주어 + be동사 + 과거분사 + 전치사 + 명사’의 어순으로 쓴다.",
  n=["과거분사 filled가 be동사 is 앞에 와서 어순이 틀렸으므로", "전치사 with가 명사 joy 뒤에 와서 어순이 틀렸으므로", "주어와 be동사가 문장 끝으로 가서 어순이 틀렸으므로", "주어 + is + filled + with + joy의 어순이 바르므로", "with joy가 동사 앞에 끼어들어 어순이 틀렸으므로"],
  st="① 낱말 가운데 주어({0})와 be동사({1})를 먼저 세운다. → ② be동사 바로 뒤에 과거분사({2})를 붙여 수동태를 만든다. → ③ 과거분사와 짝이 되는 전치사와 남은 명사({3})를 차례로 붙이면 {a}",
  R=("her heart", "is", "filled", "with joy"), B=("they", "were", "satisfied", "with the result"), C=("the room", "was", "filled", "with excitement"), D=("the mountain", "was", "covered", "with snow"),
  E=("she", "is", "known", "for her kindness"), F=("the station", "was", "crowded", "with passengers"))

X(1, 37, r="능동문을 수동태로 바꿀 때는 목적어를 주어로 삼고 동사를 ‘be동사 + 과거분사’로 쓰며, be동사의 시제는 능동문의 시제와 같게 한다. 행위자가 someone처럼 분명하지 않으면 by + 행위자를 생략한다.",
  n=["능동문이 과거(stole)인데 현재형 is stolen을 썼으므로", "has stolen은 능동의 현재완료라 ‘지갑이 훔쳤다’는 뜻이 되므로", "was stealing은 능동의 과거진행이라 수동의 뜻이 아니므로", "과거의 수동태 was stolen으로 바르게 바꿨으므로", "had stolen은 능동의 과거완료라 수동의 뜻이 아니므로"],
  st="① 능동문의 동사({0})가 과거이므로 수동태도 과거의 was/were + 과거분사여야 한다. → ② be동사가 없거나 -ing형·have + 과거분사처럼 능동인 보기, 현재형 보기를 지운다. → ③ {1} 정답은 {n}.",
  R=("stole", "행위자가 Someone이라 by 없이 쓴다."), B=("destroyed", "능동문의 주어 A storm은 by a storm으로 남겨야 뜻이 같다. by someone은 뜻이 달라진다."), C=("damaged", "행위자가 Someone이라 by 없이 쓴다. had been damaged before는 때가 달라진다."),
  D=("locked", "행위자가 Someone이라 by 없이 쓴다."), E=("repaired", "능동문의 주어 The workers는 by the workers로 남겨야 뜻이 같다. by someone은 뜻이 달라진다."),
  F=("deleted", "능동문의 주어 A hacker는 by a hacker로 남겨야 뜻이 같다. by someone은 뜻이 달라진다."))

X(1, 38, r="4형식 문장의 사물 목적어(직접목적어)를 주어로 수동태를 만들면 ‘be + 과거분사 + to + 사람’이 된다. 능동문이 과거이면 was/were를 쓴다.",
  n=["has awarded는 능동의 현재완료라 ‘상이 수여했다’는 뜻이 되므로", "과거의 수동태 was awarded 뒤에 to her를 바르게 썼으므로", "was awarding은 능동의 진행형이므로", "had awarded는 능동의 과거완료이므로", "능동문이 과거인데 현재형 is를 썼고 사람 앞에 to도 빠졌으므로"],
  st="① 능동문의 구조를 나눈다: {0}. → ② 사물 목적어({1})가 주어가 되면 동사는 과거의 수동태(was + 과거분사)가 되고, 남은 사람 목적어 앞에는 to를 붙인다. → ③ 능동형(have/had + 과거분사, was + -ing)과 현재형을 지운다. 정답은 {a}.",
  R=("awarded(동사) + her(사람) + the prize(사물)", "the prize"), B=("sent(동사) + Jane(사람) + a certificate(사물)", "a certificate"), C=("offered(동사) + Mina(사람) + a scholarship(사물)", "a scholarship"),
  D=("gave(동사) + Tom(사람) + an award(사물)", "an award"), E=("showed(동사) + us(사람) + a rare painting(사물)", "a rare painting"), F=("granted(동사) + Leo(사람) + permission(사물)", "permission"))
RV(1, 38, "BCEF", fx=True, why="수정 예시 발문의 조사가 ‘The scholarship’를, ‘Permission’를처럼 어색해 ‘을’로 고쳤다.")

X(1, 39, r="지각동사(see, hear) + 목적어 + 원형부정사 문장을 수동태로 바꾸면 원형부정사가 to부정사로 바뀐다. 목적격 보어가 현재분사이면 수동태에서도 현재분사를 그대로 쓴다.",
  k="(A) 능동태의 목적격 보어는 원형부정사 sing, (B) 수동태에서는 to부정사, (C) 그대로 유지되는 것은 현재분사이다.",
  n=["(A)는 능동태이므로 to sing이 아니라 원형부정사 sing이고, (B)·(C)도 맞지 않으므로", "(A) sing, (B) to부정사, (C) 현재분사가 모두 맞으므로", "(A)가 singing이면 수동태에서도 그대로 쓰므로 설명과 맞지 않고, (C)도 동사원형이 아니므로",
     "(B)는 과거분사가 아니라 to부정사이고 (C)도 맞지 않으므로", "(A)는 to sing이 아니라 원형부정사이고 (B)도 현재분사가 아니므로"],
  st="① 밑줄 친 수동태 문장에서 be + 과거분사 뒤의 to부정사({0})를 찾는다. → ② 능동태로 되돌리면 지각동사 뒤 목적격 보어는 to를 뗀 원형부정사({1})이다. 따라서 (A)는 {1}, (B)는 to부정사다. → ③ 수동태에서도 모양이 바뀌지 않는 보어는 진행 중인 동작을 나타내는 현재분사이므로 (C)는 현재분사다. 정답은 {n}.",
  R=("to sing", "sing"), B=("to jump", "jump"), C=("to cheer", "cheer"), D=("to cross", "cross"), E=("to sing", "sing"), F=("to laugh", "laugh"))

X(1, 40, r="사역동사 make는 능동태에서 ‘make + 목적어 + 원형부정사’로 쓰고, 수동태가 되면 ‘be made + to부정사’로 써서 생략되었던 to가 다시 나타난다.",
  n=["(B)는 완료 시제가 아니라 수동태이므로", "(A)는 능동태의 make + 목적어 + 원형부정사, (B)는 수동태에서 to가 다시 나타난 것이라고 바르게 설명했으므로", "목적어가 사물인지 사람인지는 보어의 형태와 관계가 없으므로",
     "(B)의 to realize는 목적을 나타내는 부사적 용법이 아니라 수동태의 보어이므로", "자동사인지 타동사인지는 보어의 형태와 관계가 없으므로"],
  st="① (A)와 (B)의 동사 모양을 견준다. (A)는 능동태({0}), (B)는 be동사가 붙은 수동태({1})다. → ② 사역동사 make의 목적격 보어는 능동태에서는 원형부정사, 수동태에서는 to부정사다. 차이의 원인은 태(능동/수동)뿐이다. → ③ 시제, 목적어의 종류, 부사적 용법, 자동사·타동사를 이유로 든 보기를 지운다. 정답은 {n}.",
  R=("made the hero fall", "was made to realize"), B=("made Mina stay", "was made to stay"), C=("made the player repeat", "was made to repeat"), D=("made Tom apologize", "was made to apologize"),
  E=("made us rewrite", "were made to rewrite"), F=("made the dog hide", "was made to come out"))
